import { notFound, ok, withHandler } from "@/lib/api";
import { requireRole } from "@/lib/auth/guards";
import { NO_STORE } from "@/lib/auth/http";
import { getDb } from "@/lib/db";
import { CHANGE_ID, getChange } from "@/lib/services/changes";

export const dynamic = "force-dynamic";

// Spelled out instead of `RouteContext<"/api/changes/[id]">`: that global is generated by
// `next dev`/`next build`, and CI typechecks before building.
type Context = { params: Promise<{ id: string }> };

/**
 * Admin, coordinator, faculty: one change request (`ChangeRequest`; `nl_prompt` is null except
 * for the requester and admins). `404` for an unknown or malformed id, or a request the user may
 * not see (a club gets `403`).
 */
export const GET = withHandler(async (request, context: Context) => {
  const user = await requireRole(
    request,
    "admin",
    "department_coordinator",
    "faculty",
  );
  const { id } = await context.params;
  if (!CHANGE_ID.test(id)) throw notFound("No change request with that id.");
  return ok(await getChange(await getDb(), user, id), { headers: NO_STORE });
});
